use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_HMD_log: Option<Common::Log_Impl>,
  pub api_request_log: Option<Common::Request_Impl>,
  pub api_zeroize: Option<u8>
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_HMD_log(container.api_HMD_log);
  put_request_log(container.api_request_log);
  put_zeroize(container.api_zeroize);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  HMD_log: Option<Common::Log_Impl>,
  request_log: Option<Common::Request_Impl>,
  zeroize: Option<u8>)
{
  put_HMD_log(HMD_log);
  put_request_log(request_log);
  put_zeroize(zeroize);
}

/// setter for IN EventDataPort
pub fn put_HMD_log(value: Option<Common::Log_Impl>)
{
  *extern_api::IN_HMD_log.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN EventDataPort
pub fn put_request_log(value: Option<Common::Request_Impl>)
{
  *extern_api::IN_request_log.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// getter for OUT EventDataPort
pub fn get_response_log() -> Option<Common::ResponseLog_Impl>
{
  return extern_api::OUT_response_log.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// setter for IN EventPort
pub fn put_zeroize(value: Option<u8>)
{
  *extern_api::IN_zeroize.lock().unwrap_or_else(|e| e.into_inner()) = value
}
